import{St as e,at as t,it as n,ot as r,st as i,t as a,tt as o,vt as s}from"./chunks/framework.B8HA7oqK.js";var c=JSON.parse(`{"title":"Browser Dialer","description":"","frontmatter":{},"headers":[],"relativePath":"ru/config/features/browser_dialer.md","filePath":"ru/config/features/browser_dialer.md","lastUpdated":1768735895000}`),l={name:`ru/config/features/browser_dialer.md`};function u(a,c,l,u,d,f){let p=e(`Badge`);return s(),n(`div`,null,[c[0]||=o(`h1`,{id:`browser-dialer`,tabindex:`-1`},[r(`Browser Dialer `),o(`a`,{class:`header-anchor`,href:`#browser-dialer`,"aria-label":`Permalink to “Browser Dialer”`},`​`)],-1),i(p,{text:`БЕТА`,type:`warning`}),c[1]||=r(),i(p,{text:`v1.4.1+`,type:`warning`}),c[2]||=t(`<h2 id="предыстория" tabindex="-1">Предыстория <a class="header-anchor" href="#предыстория" aria-label="Permalink to “Предыстория”">​</a></h2><p>Xray обычно использует uTLS для имитации поведения популярных браузеров, и им можно управлять с помощью настройки <code>fingerprint</code>. Однако отпечатки, создаваемые uTLS, являются несовершенной копией реальных, и поскольку uTLS является популярной библиотекой, они сами могут стать целью.</p><p>Итак, <a href="https://github.com/v2ray/discussion/issues/754#issuecomment-647934994" target="_blank" rel="noreferrer">идея Browser Dialer</a> заключается в том, что Xray использует настоящий браузер для установления TLS-соединений. Это работает так: Xray запускает небольшой веб-сайт на <code>localhost:8080</code>, пользователь открывает этот веб-сайт в выбранном им браузере, а JavaScript на этой странице будет действовать как сетевой стек Xray (HTTP-клиент, TLS-клиент).</p><p>Таким образом, поведение снятия отпечатков TLS является идеальным, и поэтому может быть возможно оживить серверы, которые отлично открываются как веб-сайты в браузере, но не подключаются с использованием какого-либо программного обеспечения для проксирования.</p><p>Однако есть много недостатков:</p><ul><li>Пользователь должен запускать браузер рядом с клиентом Xray только для открытия прокси-соединения.</li><li>Browser Dialer не должен быть туннелирован через сам прокси, иначе возникнет петля. Пользователи TUN должны быть осторожны.</li><li>Браузер может работать только со стандартным HTTP, что означает, что поддерживаются только <a href="./../transports/websocket.html">WebSocket</a> и <a href="https://github.com/XTLS/Xray-core/discussions/4113#discussioncomment-11468947" target="_blank" rel="noreferrer">XHTTP</a>.</li><li><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a> необходимо учитывать при выполнении запросов с одного веб-сайта (<code>localhost:8080</code>) на другой (<code>proxy.example.com:443</code>).</li><li>Браузер туннелирует ваш трафик с помощью JavaScript, поэтому наблюдается значительное снижение производительности (или разрядка аккумулятора).</li><li>Конфигурация, используемая с Browser Dialer, не может использовать собственные заголовки SNI или хоста. <code>SNI == host == address</code>. Пользовательские заголовки HTTP и <code>tlsSettings</code> игнорируются полностью.</li></ul><h2 id="конфигурация" tabindex="-1">Конфигурация <a class="header-anchor" href="#конфигурация" aria-label="Permalink to “Конфигурация”">​</a></h2><ol><li>Подготовьте рабочую конфигурацию WebSocket или XHTTP. Помните о вышеуказанных ограничениях.</li><li>Запустите Xray с помощью <code>XRAY_BROWSER_DIALER=127.0.0.1:8080</code>. В Windows это можно сделать как <code>set XRAY_BROWSER_DIALER=...</code>, а затем запустить ядро из консоли, в Linux ядро можно запустить как <code>XRAY_BROWSER_DIALER=127.0.0.1:8080 ./xray -c config.json</code>.</li><li>Откройте браузер, который не туннелирован через прокси, или измените маршрутизацию конфигурации таким образом, чтобы домен сервера Xray переходил к <code>freedom</code> непосредственно с клиента. Перейдите по адресу <code>localhost:8080</code> и откройте консоль разработчика с помощью <code>F12</code>, чтобы отслеживать ошибки.</li><li>Для повышения производительности и обхода произвольных ограничений на подключение, применяемых браузером, рекомендуется включить <code>Mux.Cool</code>.</li></ol><h2 id="внутренняя-работа" tabindex="-1">Внутренняя работа <a class="header-anchor" href="#внутренняя-работа" aria-label="Permalink to “Внутренняя работа”">​</a></h2><ul><li>Xray прослушивает <code>http://127.0.0.1:8080</code>, а браузер обращается к <code>http://127.0.0.1:8080</code>, чтобы загрузить <code>JS</code> на веб-страницу.</li><li><code>JS</code> активно устанавливает соединение WebSocket с <code>http://127.0.0.1:8080</code>. Xray будет использовать это соединение для отправки инструкций, но пока оно попадает в пул соединений (реализованный как канал Go).</li><li>Когда необходимо установить соединение, Xray получает доступное соединение из пула и отправляет имя протокола, целевой URL-адрес и необязательные ранние данные.</li><li>Как только <code>JS</code> успешно подключается к цели, он сообщает об этом Xray и продолжает использовать это соединение для двунаправленной пересылки данных.</li><li>После закрытия соединения с сервером соединение с localhost также закрывается, но JS гарантирует, что всегда доступно как минимум одно незанятое соединение.</li></ul><h2 id="websocket" tabindex="-1">WebSocket <a class="header-anchor" href="#websocket" aria-label="Permalink to “WebSocket”">​</a></h2>`,11),i(p,{text:`v1.4.1+`,type:`warning`}),c[3]||=t(`<p>В соответствии с потребностями браузера механизм ранних данных был скорректирован следующим образом:</p><ul><li>Заголовок ответа сервера будет содержать запрошенный <code>Sec-WebSocket-Protocol</code>, который также изначально obfuscates the length characteristic of the WSS handshake response.</li><li>Кодировка, используемая для ранних данных для браузеров, - это <code>base64.RawURLEncoding</code> вместо <code>StdEncoding</code>, и сервер сделал ее совместимой.</li><li>Кроме того, в связи с <a href="https://github.com/XTLS/Xray-core/pull/375" target="_blank" rel="noreferrer">Xray-core#375</a> рекомендациями по <code>?ed=2048</code> этот PR также увеличил сервер <code>MaxHeaderBytes</code> на 4096. <s>(Хотя, похоже, это будет работать и без модификации.)</s></li></ul><h2 id="xhttp" tabindex="-1">XHTTP <a class="header-anchor" href="#xhttp" aria-label="Permalink to “XHTTP”">​</a></h2>`,3),i(p,{text:`v1.8.19+`,type:`warning`}),c[4]||=o(`p`,null,[o(`a`,{href:`https://github.com/XTLS/Xray-core/discussions/4113#discussioncomment-11468947`,target:`_blank`,rel:`noreferrer`},`XHTTP`),r(` поддерживает QUIC, но также может использоваться собственный стек QUIC браузера. В Chrome это можно сделать через `),o(`code`,null,`chrome://flags`),r(`, в других браузерах он может быть уже включен или для него может потребоваться другой флаг.`)],-1),c[5]||=o(`p`,null,[r(`В общем, `),o(`code`,null,`tlsSettings`),r(` полностью игнорируются при использовании Browser Dialer. Xray никак не контролирует, какую версию HTTP выбирает браузер.`)],-1)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};